// Wave 6.1.2: Bundle JS dependencies and generate config for the tray webview.
// 1. Copies pre-built UMD bundles from node_modules into dist/vendor/
// 2. Generates dist/config.js from environment variables (if set) or leaves
//    the existing config.js untouched (so developers can use their own copy).
//
// Run: node scripts/bundle-deps.js
// This script is called automatically by `npm run build` before `tauri build`.

import { copyFileSync, mkdirSync, existsSync, writeFileSync } from 'fs';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const trayRoot = resolve(__dirname, '..');

const distVendor = resolve(trayRoot, 'dist/vendor');
if (!existsSync(distVendor)) {
  mkdirSync(distVendor, { recursive: true });
}

// ── 1. Vendor bundles ────────────────────────────────────────────────────────

/**
 * Search for a package file in node_modules starting from startDir and walking
 * up to the monorepo root (npm hoisting may place packages higher up).
 */
function findPackageFile(packageName, relativeSourcePath, startDir) {
  let dir = startDir;
  for (let i = 0; i < 6; i++) {
    const candidate = resolve(dir, 'node_modules', packageName, relativeSourcePath);
    if (existsSync(candidate)) {
      return candidate;
    }
    const parent = resolve(dir, '..');
    if (parent === dir) break;
    dir = parent;
  }
  return null;
}

function copyVendor(packageName, relativeSourcePath, outputName) {
  const sourcePath = findPackageFile(packageName, relativeSourcePath, trayRoot);
  if (!sourcePath) {
    console.error(
      `[bundle-deps] ERROR: Cannot find ${packageName}/${relativeSourcePath} ` +
      `starting from ${trayRoot}. Run npm install first.`
    );
    process.exit(1);
  }
  const dest = resolve(distVendor, outputName);
  copyFileSync(sourcePath, dest);
  console.log(`[bundle-deps] Vendor: ${packageName} -> dist/vendor/${outputName}`);
}

// @supabase/supabase-js UMD bundle (no bundler required in the webview)
copyVendor('@supabase/supabase-js', 'dist/umd/supabase.js', 'supabase.js');

// ── 2. Config generation ─────────────────────────────────────────────────────
// If the Supabase env vars are set (CI / production build), generate config.js.
// If they are not set, keep the existing config.js (developer's manual copy).

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

const configPath = resolve(trayRoot, 'dist/config.js');

if (supabaseUrl && supabaseAnonKey) {
  const configContent = `// Auto-generated by scripts/bundle-deps.js — do not edit manually.
// Source: NEXT_PUBLIC_SUPABASE_URL / NEXT_PUBLIC_SUPABASE_ANON_KEY env vars.
window.CORIVEN_CONFIG = {
  supabaseUrl: ${JSON.stringify(supabaseUrl)},
  supabaseAnonKey: ${JSON.stringify(supabaseAnonKey)},
};\n`;
  writeFileSync(configPath, configContent, 'utf8');
  console.log('[bundle-deps] Config: generated dist/config.js from environment variables');
} else if (existsSync(configPath)) {
  console.log('[bundle-deps] Config: dist/config.js already exists — skipping generation');
} else {
  console.warn(
    '[bundle-deps] WARNING: dist/config.js not found and env vars not set.\n' +
    '  Copy dist/config.example.js to dist/config.js and fill in your values,\n' +
    '  or set NEXT_PUBLIC_SUPABASE_URL + NEXT_PUBLIC_SUPABASE_ANON_KEY.'
  );
}

console.log('[bundle-deps] Done.');
